    features:[['Kasino ja vedonlyönti','Kolikkopelit, live-kasino, jackpotit sekä ennakko-, live- ja virtuaalivedot samalla tilillä.'],['100 % enintään 500 € + 200 kierrosta','Ensimmäinen hyväksyttävä talletus on vähintään 20 €.'],['Erillinen vedonlyöntibonus','Perustarjous 100 % enintään 100 €; maarajat ja kierrätys vaihtelevat.'],['Tunnettuja peliyhtiöitä','Pragmatic Play, Hacksaw Gaming, Playtech ja Playson näkyvät aulassa.'],['VIP-kohtaiset nostorajat','Eurotaulukko alkaa 500 eurosta päivässä ja 7 000 eurosta kuukaudessa.'],['Kauppa ja turnaukset','Kolikot, haasteet, turnaukset ja VIP-tasot tuovat lisäpalkintoja.']],
