    verdict:[['Kasinon tervetulotarjous','100 % enintään 500 € + 200 kierrosta','Valitse kasino- tai vedonlyöntibonus, ei molempia.'],['Kierrätys','Talletus + bonus 35x; kierrosvoitot 40x','100 € talletus ja 100 € bonus vaativat 7 000 € hyväksyttäviä panoksia.'],['Alin VIP-taso','500 € päivässä / 7 000 € kuukaudessa','Muut tasot ja valuutat käyttävät eri rajoja.'],['Lisenssi ja operaattori','Ei riippumatonta vahvistusta','Ulkoiset hakemistot ovat ristiriidassa; pyydä ajantasaiset oikeudelliset tiedot.']],
    bonusIntro:'Aktivoi tarjous My Bonus -kohdasta ennen pelaamista. Minimi on 20 €; Skrill ja Neteller eivät kelpaa. Vain yksi bonus voi olla aktiivinen. Nostopyyntö voi peruuttaa bonuksen tai oikeuden siihen.',
    bonus:[['Ensitalletus','100 % enintään 500 € + 200 kierrosta','Muiden valuuttojen rajat näkyvät kampanjassa.'],['Kierrosten jako','20 päivässä kymmenen päivän ajan','Lunasta erä 24 tunnissa; suorita aktiivinen kasinobonus ensin.'],['Bonuskierrätys','Talletus + bonus 35x kymmenessä päivässä','Hyväksytyt kolikkopelit yleensä 100 %, pöytä-/korttipelit 0 %, live-pelit 10 %.'],['Kierrosvoitot','40x kierrätys','Muuntoraja 50 € enintään 50 kierrokselle, 100 € yli 50 kierrokselle. Varmista soveltaminen päiväeriin.'],['Panos ja muunto','Tarjouksen maksimipanos 100 €; muunto enintään 10x bonus','Yleisissä ehdoissa on ristiriitainen panosrajan sanamuoto; selvitä ennen pelaamista.'],['Rajatut pelit','Osa ei kierrätä tai on kielletty bonuksella','Tarkista voimassa olevat listat; oikea raha käytetään ensin.']],
    games:[['Kolikkopelit ja jackpotit','Laskurit näyttivät yli 11 000 kolikkopeliä ja 13 000 peliä yhteensä. Muuttuvat luetteloluvut eivät takaa jokaisen pelin saatavuutta kaikissa maissa.'],['Pöydät ja live-kasino','Ruletti, blackjack, baccarat, nopat, pokeri ja game show -pelit omissa live-luokissaan. Myös European Roulette, Jacks or Better ja Texas Holdem Bonus näkyvät.'],['Näkyvät peliyhtiöt','Pragmatic Play, Pragmatic Live, Hacksaw Gaming, Playtech, Playson, Amusnet, Novomatic, BGaming, Betsoft, Yggdrasil ja Thunderkick.'],['Uutuudet','Le Bandit Monsters Unleashed, Sun Totem: Hold & Win, Moon Dynasty, Lightning Diamond Double Strike VIP (3x3), Joker’s Mega Fortune ja Battle Thunder.']],
    sports:[['Vedonlyönnin tervetulobonus','Perusraja 100 % enintään 100 €, minimitalletus 20 €. Italia enintään 150 €. Suomi, Norja, Sveitsi ja Itävalta: 200 € / 2 000 NOK / 220 CHF valuutan mukaan.'],['Aktivointi ja kierrätys','Ensin ratkaistuja vetoja talletuksen 1x verran kertoimella vähintään 1,50. Sitten talletus + bonus 6x, Suomessa, Norjassa, Sveitsissä ja Itävallassa 5x. Aikaa 30 päivää.'],['Hyväksyttävät vedot','Yksittäisvedoissa vähintään 2,00, yhdistelmissä 1,50 jokaiselle kohteelle. Vain tapahtuman ensimmäinen ratkaistu veto lasketaan, enintään 50 € vastaava panos.'],['Toistuvat kampanjat','Näkyvissä viikonlopun reload 50 % enintään 700 € + 50 kierrosta, kasinon cashback 15 % enintään 3 000 € ja live-cashback 25 % enintään 200 €. Urheilutarjouksilla on omat ehtonsa.'],['Kauppa ja VIP','Kolikot, haasteet ja turnaukset tuovat palkintoja. VIP arvioi 90 päivän aktiivisuutta; kuukauden tauko voi alentaa tasoa.']],
    cashierIntro:'Julkinen Kanada/CAD-valinta näytti Interacin, kortit, Netellerin, MiFinityn ja kryptovaluuttoja. Saatavuus riippuu maasta, valuutasta ja tilin tarkistuksesta. Bonuksen 20 € minimi ei ole yleinen maksuminimi.',
    cashier:[['Maksutavat','Interac, kortit, Neteller, MiFinity; BTC, ETH, LTC ja USDT','Käytä omia maksuvälineitä; nosto talletustavalle mahdollisuuksien mukaan.'],['Talletuksen käyttö','Vähintään 1x; ehdoissa myös 20 € kuukausipanoksia','Muuten mahdollinen hylkäys ja 10 % maksu, korteilla/pankkisiirroilla 15 %.'],['VIP-rajat','Päivä/kuukausi: 500/7 000 €, 500/10 000 €, 800/12 000 €, 5 000/15 000 €, 5 000/20 000 €','Enintään kolme odottavaa pyyntöä; tarkista tilin taso ja valuutta.'],['Käsittely','Enintään kolme arkipäivää tarkistusten jälkeen','Maanantai–perjantai 06–17 GMT; maksupalvelun aika tulee lisäksi.'],['KYC','Henkilöllisyys, osoite, maksuvälineen omistus ja tarvittaessa varojen alkuperä','Asiakirjat 30 päivässä; tarkistus yleensä enintään kymmenen päivää täydestä vastauksesta, joskus kauemmin.'],['Passiivinen tili','180 päivän kirjautumistauon jälkeen mahdollinen 5 € kuukausimaksu','Tarkista saldo ja tilin tila ennen pitkää taukoa.']],
    safety:[['Lisenssi ja yhtiö','Tarkistettu alatunniste ja ehdot eivät yksilöineet selvästi varmennettavaa lisenssiä ja operaattoria. Ulkoiset hakemistot ovat ristiriidassa. Saatavuus ei osoita paikallista lupaa.'],['Tuki ja valitukset','Chat ja tukisähköposti on julkaistu. Ratkaisemattoman asian voi viedä kirjalliseen valitukseen; vastaus kymmenessä päivässä, monimutkaisissa tapauksissa pidennys mahdollinen. Säilytä todisteet.'],['Vastuullinen pelaaminen','Itsearviointi, tauko ja pelikielto tuen kautta on kuvattu. Sulkeminen mahdollisimman pian ilman tarkkaa määräaikaa. Välittömiä talletus-/tappiorajoja ei vahvistettu. Vain aikuisille; pelaaminen ei ole tulonlähde.']],
